import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
B="http://localhost:8080"
tok=None
log={}
def req(path, method="GET"):
    global tok
    for attempt in range(200):
        h={}
        if path!="/token":
            if not tok: tok=json.loads(raw("/token","POST")[1])["token"]
            h["Authorization"]="Bearer "+tok
        code,body,hdr=raw(path,method,h)
        log[code]=log.get(code,0)+1
        if code==200:
            try: return json.loads(body)
            except Exception: print("bad json",path,body[:200]); continue
        if code==404: return None
        print(path,code,body[:200],dict(hdr))
        if code==401 or code==403: tok=None; continue
        ra=hdr.get("Retry-After")
        try: w=float(ra)
        except Exception:
            try: w=float(json.loads(body).get("retry_after"))
            except Exception: w=1
        time.sleep(w)
    raise SystemExit("gave up "+path)
def raw(path,method="GET",h={}):
    r=urllib.request.Request(B+path,method=method,headers=h,data=b"" if method=="POST" else None)
    try:
        with urllib.request.urlopen(r) as f: return f.status,f.read().decode(),f.headers
    except urllib.error.HTTPError as e: return e.code,e.read().decode(),e.headers
pages={}
p=1
while p:
    d=req(f"/orders?page={p}")
    pages[p]=d
    print("page",p,d["total_pages"],len(d["items"]),d["next"])
    nxt=d["next"]
    p=int(nxt.split("page=")[1]) if nxt else 0
json.dump(pages,open("/tmp/work/pages.json","w"))
orders=[o for p in pages.values() for o in p["items"]]
seen={};dups=0
for o in orders:
    if o["id"] in seen:
        dups+=1
        if seen[o["id"]]!=o: print("DUP DIFFERS",seen[o["id"]],o)
    else: seen[o["id"]]=o
print(len(orders),len(seen),dups,set(o["status"] for o in orders))
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
q=[]
for o in seen.values():
    if o["status"]!="shipped": continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: print("naive",o)
    if lo<=t<hi: q.append(o)
cust={}
for o in q:
    c=o["customer_id"]
    if c not in cust: cust[c]=req(f"/customers/{c}")
    if cust[c] is None: print("missing customer",o)
reg={"north":0,"south":0,"east":0,"west":0}
for o in q:
    c=cust[o["customer_id"]]
    n=o["amount_cents"]*(100-c["discount_pct"])
    v=(n+50)//100
    reg[c["region"]]+=v
res={"total_cents":sum(reg.values()),"order_count":len(q),"duplicates_skipped":dups,"by_region":reg}
print(res,log)
json.dump(res,open("/workspace/result.json","w"),indent=2)
